	public WishlistItem updateWishlistItem( UpdateWishlistItemCommand command ) {

		WishlistItem entity = new WishlistItem();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setWishlistItemId( command.getWishlistItemId() );
            entity.setAddedDate( command.getAddedDate() );
            entity.setWishlist( command.getWishlist() );
            entity.setVariant( command.getVariant() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of WishlistItem {0} ", entity.toString() );

		return entity;
	}

